def find_hybrid(self, query, k=3, rrf_k=60):
        """Both indexes, fused by rank -- BM25 and cosine together, the usual "hybrid search".

        Fused on **ranks** rather than scores, because the two scores share no scale and never
        will: FTS5's BM25 is negative and corpus-dependent, cosine sits in a narrow band off
        zero. Normalising them into comparability runs into the trap `03_operations` covers,
        where min-max promotes the least-bad of a bad batch to 1.0. Ranks have no such failure:

            score(d) = sum over each index of  1 / (rrf_k + rank of d in that index)

        `rrf_k` (conventionally 60) flattens the gap between the top few positions, so one index
        being confidently wrong cannot dominate the other.

        This generalises what an exact-first rule cannot. Answering `PGRST204` by trying FTS5
        and falling back to vectors works *because that query is a label* and you can tell by
        looking. An ordinary question has no such tell, and exact-first would discard the vector
        ranking whenever any single word happened to match.

        Chroma implements this natively -- `Search().rank(Rrf([Knn(...), Knn(...)]))` over a
        BM25 sparse index -- but `Search` raises `NotImplementedError: Search is not implemented
        for Local Chroma`. It works on distributed and hosted Chroma only, which is why the
        fusion is done here by hand.
        """
        lexical = self._fts_query(query)
        try:
            lex_ids = [row["id"] for row in self.find_exact(lexical, limit=10)] if lexical else []
        except sqlite3.OperationalError:
            lex_ids = []          # a query that is all stopwords, or all punctuation
        vec_ids = [i for _s, i, _t in self.find_like(query, k=len(self))]

        fused = {}
        for ranking in (lex_ids, vec_ids):
            for rank, entry_id in enumerate(ranking):
                fused[entry_id] = fused.get(entry_id, 0.0) + 1.0 / (rrf_k + rank + 1)

        best = sorted(fused.items(), key=lambda kv: -kv[1])[:k]
        return [(score, eid, self.get(eid)["text"]) for eid, score in best], lex_ids, vec_ids

    def recent(self, about=None, source=None, limit=5):
        """The journal has fields too -- they just were not designed before the first entry."""
        where, args = [], []
        for column, value in (("about", about), ("source", source)):
            if value:
                where.append(f"{column} = ?"); args.append(value)
        clause = ("WHERE " + " AND ".join(where)) if where else ""
        args.append(limit)
        return self.db.execute(
            f"SELECT * FROM entries {clause} ORDER BY at DESC LIMIT ?", args
        ).fetchall()

    def count(self, **filters):
        where = " AND ".join(f"{k} = ?" for k in filters)
        clause = ("WHERE " + where) if where else ""
        return self.db.execute(
            f"SELECT COUNT(*) AS n FROM entries {clause}", list(filters.values())
        ).fetchone()["n"]

    def values(self, field):
        """Every value a field has taken. Fine to enumerate when there are a handful."""
        return [r["value"] for r in self.db.execute(
            "SELECT value FROM field_values WHERE field = ? ORDER BY value", (field,))]

# INJECTED by a retrieval, `Records` and `Graph` are CALLED as tools, and skills are PICKED from
# a catalogue that is always present. They spend one budget between them, which is the only
# reason this chapter needs to tell them apart.
ROUTES = {
    "profile": "pasted",
    "catalogue": "catalogue",
    "retrieval": "injected",
    "constraints": "rules",
    "scratchpad": "run",
    "notes": "run",
    "conversation": "run",
}


def route(item):
    if item.source.startswith("journal#"):
        return "injected"
    if item.source.startswith("step_outputs"):
        return "called"
    if item.source.startswith(("extracted from", "summary of")):
        return "compressed"
    return ROUTES.get(item.source.split(",")[0], "run")


def by_route(items):
    """{route: tokens} -- where a context's size actually went."""
    totals = {}
    for item in items:
        totals[route(item)] = totals.get(route(item), 0) + item.tokens
    return dict(sorted(totals.items(), key=lambda kv: -kv[1]))

if pending_call is not None:
        # A tool call with nothing reported on it yet, which is where the loop is when `Observe`
        # runs: `Act` has carried the decision out, and the tool message that would fuse the two
        # into one observation is the thing `Observe` is about to produce. Left out, the only
        # component whose job is to describe that call could not see which call it was -- it
        # gets the tool's name from `conversation.pending` and never its arguments.
        tool, args, at = pending_call
        items.append(Item("decision", f"{tool}({args})", at, about=f"{tool} {args}"))

    now = len(messages)
    for note in getattr(conversation, "notes", None) or []:
        items.append(Item("fact", note, now, source="notes"))
    if scratchpad is not None:
        for key, value in scratchpad.entries.items():
            items.append(Item("state", f"{key}: {value}", now, about=f"scratchpad:{key}",
                              source="scratchpad"))
    for rule in constraints:
        items.append(Item("constraint", rule, 0, source="constraints", pinned=True))
    for key, value in (profile.items() if hasattr(profile, "items") else
                       getattr(profile, "data", {}).items() if profile is not None else ()):
        items.append(Item("fact", f"{key}: {value}", 0, about=f"profile:{key}", source="profile"))
    for skill in catalogue:
        items.append(Item("instruction", skill, 0, source="catalogue"))

    return sorted(items, key=lambda i: i.turn)

@dataclass
class Selection:
    kept: list
    dropped: list = field(default_factory=list)   # [(item, why)]

    @property
    def tokens(self):
        return tokens(self.kept)

    def report(self, width=70):
        lines = [f"kept {len(self.kept)} items, {self.tokens} tokens"]
        for item in self.kept:
            mark = "pinned" if item.pinned else "      "
            lines.append(f"  + {mark} t{item.turn:<3} {item.kind:<11} {_short(item.content, width)}")
        if self.dropped:
            lines.append(f"dropped {len(self.dropped)}")
            for item, why in self.dropped:
                lines.append(f"  -        t{item.turn:<3} {item.kind:<11} "
                             f"{_short(item.content, width - 20)}  <- {why}")
        return "\n".join(lines)


def _short(text, width):
    text = " ".join(text.split())
    return text if len(text) <= width else text[: width - 3] + "..."


def supersede(items):
    """Newest version of every `about`, and everything with no `about` at all.

    Returns (current, [(old_item, why)]).
    """
    newest = {}
    for item in items:
        if item.about:
            # the same `about` can hold an observation AND a raw result; they are versions
            # only of their own kind, never of each other
            newest[(item.kind, item.about)] = item.turn
    current, dropped = [], []
    for item in items:
        latest = newest.get((item.kind, item.about)) if item.about else None
        if latest is not None and item.turn < latest:
            dropped.append((item, f"superseded at t{latest}"))
        else:
            current.append(item)
    return current, dropped

if candidates:
        now = max(i.turn for i in items)
        rel = unit([relevance(query, i.content) for i in candidates])
        imp = unit([IMPORTANCE[i.kind] for i in candidates])
        rec = unit([0.5 ** ((now - i.turn) / half_life) for i in candidates])
        scored = sorted(
            ((w_relevance * r + w_importance * m + w_recency * c, n, item)
             for n, (item, r, m, c) in enumerate(zip(candidates, rel, imp, rec))),
            key=lambda s: (-s[0], s[1]),
        )
        # floors, chosen AFTER scoring so each group keeps its best rather than its first
        promised = []
        for name, least in (floors or {}).items():
            group = [item for _, _, item in scored
                     if name in (route(item), item.kind) and id(item) not in chosen]
            for item in group[:least]:
                chosen.add(id(item))
                promised.append(item)
        if budget is not None and tokens(pinned) + tokens(promised) > budget:
            raise ValueError(
                f"pinned items and the floors {floors} come to "
                f"{tokens(pinned) + tokens(promised)} tokens, over the budget of {budget}. A "
                "floor is a promise, so this is refused rather than half-kept. Raise the budget, "
                "lower a floor, or compress what they hold."
            )

        spent = tokens(pinned) + tokens(promised)
        for score, _, item in scored:
            if id(item) in chosen:
                continue
            if budget is None or spent + item.tokens <= budget:
                chosen.add(id(item))
                spent += item.tokens
            else:
                dropped.append((item, f"over budget (score {score:.2f})"))

    kept = [i for i in current if id(i) in chosen]
    return Selection(kept, sorted(dropped, key=lambda d: d[0].turn))

def available(self, conversation):
        return available(conversation, self.scratchpad, self.constraints,
                         profile=self.profile, catalogue=self.catalogue)

    def focus(self, component, policy):
        """`component`, wrapped so that every call gets a context built by this system."""
        return Focus(component, scratchpad=self.scratchpad, constraints=self.constraints,
                     profile=self.profile, catalogue=self.catalogue,
                     prepare=lambda items, conversation: self.apply(items, conversation, policy))

    def items(self, conversation, policy):
        """The context a policy produces, without a component -- for a call you make yourself."""
        return self.apply(self.available(conversation), conversation, policy)

def render(opinions):
    return "\n\n".join(
        f"{name} says {o.position} ({'confident' if o.confident else 'not confident'})\n"
        f"  because: {o.because}\n  checked: {o.evidence}"
        for name, o in opinions.items())

"""Real calls and tokens for a stretch of code, from the API's own `usage` field.

Every component that talks to a model -- Think, Observe, extract -- goes through the one client in
`llm.py`, so wrapping that client's `create` sees all of them, including calls made inside other
agents and in other threads. Notebook 1 wrote this inline; it moved here when notebook 2 needed it too.

    with Meter() as meter:
        agent.run(task)
    meter.summary()   # {"calls": 3, "prompt": ..., "completion": ..., "total": ..., "seconds": ...}
"""

import time

import llm


class Meter:
    def __enter__(self):
        self.calls = []
        real = self._real = llm.client.chat.completions.create

        def create(*args, **kwargs):
            response = real(*args, **kwargs)
            self.calls.append({
                # the first user message says which task a call was working on, which is how calls
                # made by different agents at the same time are told apart afterwards
                "asked": next((m["content"] for m in kwargs.get("messages", [])
                               if m.get("role") == "user"), ""),
                "prompt": response.usage.prompt_tokens,
                "completion": response.usage.completion_tokens,
            })
            return response

        llm.client.chat.completions.create = create
        self._started = time.monotonic()
        return self

    def __exit__(self, *exc):
        self.seconds = time.monotonic() - self._started
        llm.client.chat.completions.create = self._real

    def summary(self):
        prompt = sum(c["prompt"] for c in self.calls)
        completion = sum(c["completion"] for c in self.calls)
        return {"calls": len(self.calls), "prompt": prompt, "completion": completion,
                "total": prompt + completion, "seconds": round(self.seconds)}

SERIAL = re.compile(r"^AR2-(\d{4})-(\d{5})$")


def _parse(serial):
    match = SERIAL.match(serial.strip().upper().replace("‑", "-"))
    if not match or match.group(1) not in _BATCHES:
        return None
    return match.group(1), int(match.group(2))


def _lot(batch, number):
    if batch == "2408":
        return "VC-7731"
    if batch == "2409":
        # the first 1,800 units of September's batch were built from the tail of the same cell lot
        return "VC-7731" if number <= 1800 else "VC-7740"
    return "VC-7702"


@tool
def lookup_serial(serial: Annotated[str, "Serial number, e.g. AR2-2408-01422"]) -> str:
    """Look up an Aria 2 serial number: its batch, when it shipped, and whether it is in the recall."""
    parsed = _parse(serial)
    if parsed is None:
        return f"No Aria 2 unit has the serial number {serial}."
    batch, number = parsed
    info = _BATCHES[batch]
    if number > info["units"]:
        return f"No Aria 2 unit has the serial number {serial}."
    status = "IN THE RECALL" if info["recalled"] else "not in the recall"
    return f"{serial}: batch AR2-{batch}, shipped {info['shipped']}. {status}."


@tool
def cell_lot(serial: Annotated[str, "Serial number, e.g. AR2-2409-01544"]) -> str:
    """Which battery cell lot a unit was built with."""
    parsed = _parse(serial)
    if parsed is None or parsed[1] > _BATCHES[parsed[0]]["units"]:
        return f"No Aria 2 unit has the serial number {serial}."
    return f"{serial} was built with battery cells from lot {_lot(*parsed)}."


@tool
def test_results(lot: Annotated[str, "Cell lot, e.g. VC-7731"]) -> str:
    """What testing has found for a battery cell lot."""
    return _TESTS.get(lot.strip().upper(), f"No test results on file for lot {lot}.")

def tools(self, agent):
        """The write tool for one agent, with its name and the fields it owns already in it."""
        owned = [f for f, who in self.owner.items() if who == agent]
        if not owned:
            return []
        described = ", ".join(f"{f} ({self.fields.get(f, '')})" for f in owned)

        def record(
            field: Annotated[str, f"Which field to set. Yours are: {described}"],
            value: Annotated[str, "The value, short and exact -- what the others will read."],
        ) -> str:
            """Record something the rest of the team needs, on the shared board."""
            try:
                before = self.set(agent, field, value)
            except Denied as refused:
                return f"Refused: {refused}"
            return (f"{field} is now: {value}" if before is None
                    else f"{field} changed from '{before}' to '{value}'")

        return [Tool(record, name="record")]

"""A second demo server, this one offering resources and prompts. Used by notebook 3.

`server.py` stays tools-only on purpose. Notebook 1's finding depends on it: a server that
*declares* the resources and prompts capabilities and has none of either, which is what most
of the ecosystem looks like. Adding data to it would have quietly deleted that lesson.

So the data lives here instead, which is also the more honest arrangement -- a weather service
and an archive of its readings are two different things, and in practice they are two servers
written by two different people. This file imports nothing from `demo_tools.py` for that
reason: a separate service does not get to reach into another one's variables, and having it
do so would have made the separation a story rather than a fact.

Three resources, chosen to make the distinction arguable rather than abstract: one small, one
far too large for a context window, and one parameterised. Plus the one prompt, so notebook 3
can look at a real one before recommending against bothering with them.
"""

import json
import sys

from mcp.server.mcpserver import MCPServer

# This archive's own record of which stations it holds. Deliberately not imported from
# `demo_tools`: the two servers agree about the world because they describe the same world,
# not because they share a variable.
STATIONS = {"tokyo": 18, "oslo": 4, "cairo": 33}

server = MCPServer("forge-data", version="0.1.0")


def log(message):
    """stdout is the protocol; stderr is not. Same rule as `server.py`."""
    print(message, file=sys.stderr, flush=True)


@server.resource("weather://stations", mime_type="application/json")
def stations() -> str:
    """The stations this service has readings for."""
    return json.dumps(sorted(STATIONS))


@server.resource("weather://history", mime_type="text/csv")
def history() -> str:
    """Every reading ever taken. Deliberately far larger than a context window wants."""
    rows = ["date,city,celsius"]
    for day in range(1, 366):
        for city, base in STATIONS.items():
            rows.append(f"2026-{(day % 12) + 1:02d}-{(day % 28) + 1:02d},{city},{base + day % 7}")
    return "\n".join(rows)


@server.resource("weather://station/{city}", mime_type="application/json")
def station(city: str) -> str:
    """One station's details. A resource template -- the URI carries the argument."""
    return json.dumps({"city": city, "celsius": STATIONS.get(city.lower()), "source": "forge-data"})


@server.prompt(description="Ask for a plain-language weather briefing for a city.")
def briefing(city: str) -> str:
    return f"Give me a short weather briefing for {city}. Mention whether I need a coat."


if __name__ == "__main__":
