def _repeatable(mcp_tool):
    """Whether calling this again after a timeout is safe.

    MCP lets a server say so with `readOnlyHint` / `idempotentHint`. When it says nothing, the
    answer is no -- not because the tool is probably dangerous, but because we do not know, and
    this flag is only ever read after a timeout, where not knowing is exactly the situation
    that calls for caution.
    """
    hints = getattr(mcp_tool, "annotations", None)
    if hints is None:
        return False
    return bool(getattr(hints, "read_only_hint", False) or getattr(hints, "idempotent_hint", False))


def remote_tool(session, mcp_tool, name=None, strict=True):
    """One discovered MCP tool, as a `Tool` that `Registry` and `invoke()` can hold."""

    def call(**kwargs):
        result = session.call(mcp_tool.name, kwargs)

        meta = result.meta or {}
        kind = meta.get("forge/kind")
        cause = meta.get("forge/cause")

        if not result.is_error:
            return _text(result)

        if kind is None:
            kind = UNKNOWN_FAILURE

        if kind == "refused" or kind == "bad_arguments":
            # bad_arguments should be impossible -- SchemaArgs checked before we sent. If a
            # server says it anyway, its schema and its behaviour disagree, and that is still
            # something the model can act on.
            raise ToolError(_text(result))
        if kind == "unverified":
            raise VerificationError(_text(result))
        if kind == "timeout":
            raise concurrent.futures.TimeoutError(_text(result))
        # "broken", and anything a future server invents that we do not recognise.
        raise RuntimeError(cause or _text(result))

    return Tool(
        call,
        name=name or mcp_tool.name,
        description=mcp_tool.description or "",
        args=SchemaArgs(mcp_tool.input_schema, f"{mcp_tool.name}Arguments", strict=strict),
        repeatable=_repeatable(mcp_tool),
    )


def resource_reader(session, name="read_resource", uris=()):
    """A resource, handed to the model as a tool it may choose to call.

    Resources are host-pulled by design: the host reads one and decides whether it belongs in
    the context window. This inverts that, and it is what most real hosts actually ship,
    because an agent with no human at the wheel has nobody to do the choosing.

    The trade is worth stating rather than assuming. Host-pulled, the data arrives reliably and
    costs its tokens every single turn whether or not it was needed. Model-pulled, it costs
    nothing until asked for -- and the model has to think to ask, which it often does not.

    One thing comes back for free, and it is not a small one: as a tool, a resource read goes
    through `invoke()`, so `max_tokens` applies. A host that pastes `weather://history` into the
    window has no such limit and no warning.
    """
    listed = list(uris) or [str(r.uri) for r in session.list_resources()]
    allowed = ", ".join(listed) if listed else "(none listed)"

    def read(uri: str) -> str:
        try:
            contents = session.read_resource(uri).contents
        except MCPError as e:
            # A URI the server does not have. This arrives as a protocol error rather than as
            # `is_error`, so without this it lands in the `except Exception` arm of `invoke()`
            # and is classified `broken` -- hidden from the model as a fault it cannot fix.
            # It is the opposite: naming a resource that does not exist is exactly the kind of
            # mistake the model can correct, given the list.
            raise ToolError(f"{e}. Available: {allowed}") from e
        return "\n".join(
            getattr(c, "text", f"<{getattr(c, 'mime_type', 'binary')}>") for c in contents
        )

    read.__doc__ = f"Read one of this server's resources by URI. Available: {allowed}"
    return Tool(read, name=name)

def _give_up(self, connection):
        """What the conversation is told when the server is not coming back.

        This one does go to the model, because it changes what is worth attempting. Written as
        a fact about the world rather than as an error, for the same reason `ToolError` messages
        are: the useful half is what to do now, not what went wrong.
        """
        try:
            connection.close()
        except Exception:  # noqa: BLE001 -- already giving up; a failed close changes nothing
            pass
        return {
            "role": "tool",
            "content": (f"The {self.name} service is unreachable and its tools cannot be used. "
                        f"Answer from what you already know, or say what you cannot do."),
        }

    @staticmethod
    def _suspect(conversation):
        """Whether the last turn looks like it hit a dead server.

        A guess, and known to be one. The `kind` is gone by the time a result reaches `pending`,
        so this matches on the phrasing `invoker()` uses for a withheld failure. Good enough to
        skip pings on turns where nothing went wrong, and not good enough to be the only check --
        which is why a match is followed by a ping rather than believed.
        """
        pending = getattr(conversation, "pending", None)
        if isinstance(pending, dict) and "could not be completed" in str(pending.get("content")):
            return True
        last = conversation.messages[-1] if conversation.messages else {}
        return "could not be completed" in str(last.get("content", ""))

def __exit__(self, *exc):
        if self._loop is not None and self._stop is not None:
            self._loop.call_soon_threadsafe(self._stop.set)
        if self._thread is not None:
            # `startup`, not `timeout`: shutting the child down is process work, not call work,
            # and a session configured for one-second calls still needs longer than that to
            # close cleanly.
            self._thread.join(self.startup)
        return False

    def _await(self, coro, timeout=None):
        """Run a coroutine on the session's loop and block until it answers."""
        if self._client is None:
            raise RuntimeError("session is not open")
        future = asyncio.run_coroutine_threadsafe(coro, self._loop)
        return future.result(timeout or self.timeout)

    def list_tools(self):
        return self._await(self._client.list_tools()).tools

    def call(self, name, args, timeout=None):
        return self._await(self._client.call_tool(name, args), timeout)

    def list_resources(self):
        """The server's concrete resources. Does NOT include templates -- see below."""
        return self._await(self._client.list_resources()).resources

    def list_resource_templates(self):
        """Parameterised resources, which `list_resources` leaves out entirely.

        A separate call, and easy to miss: a server offering nothing but templates answers
        `resources/list` with `[]`, and a host that asks only that concludes it has no data.
        """
        return self._await(self._client.list_resource_templates()).resource_templates

    def read_resource(self, uri, timeout=None):
        return self._await(self._client.read_resource(uri), timeout)

    def list_prompts(self):
        return self._await(self._client.list_prompts()).prompts

    def get_prompt(self, name, args=None, timeout=None):
        return self._await(self._client.get_prompt(name, args or {}), timeout)

    def ping(self, timeout=None):
        """The protocol's own liveness check -- which this SDK's servers do not answer.

        `ping` is in the MCP spec and `Client.send_ping()` sends it, but a server built with
        `MCPServer` replies `MCPError: Method not found`. Kept because it is the right call to
        make against a server that implements it, and because the alternative -- see
        `Connection.healthy()` -- is only necessary once you know this one does not work.
        """
        return self._await(self._client.send_ping(), timeout)

    @property
    def server_name(self):
        return self._client.server_info.name if self._client else None

def list_tools(self):
        return self._live().list_tools()

    def list_resources(self):
        return self._live().list_resources()

    def list_resource_templates(self):
        return self._live().list_resource_templates()

    def read_resource(self, uri, timeout=None):
        return self._live().read_resource(uri, timeout)

    def list_prompts(self):
        return self._live().list_prompts()

    def get_prompt(self, name, args=None, timeout=None):
        return self._live().get_prompt(name, args, timeout)

    @property
    def server_name(self):
        return self.session.server_name if self.session else None

## Retrieval

The policy wording is split **one document per clause**, because the clause is the unit an answer cites. Chapter 4's Gemini `embed()` goes behind LangChain's `Embeddings` interface — two methods, one for documents and one for queries, which is also the split Gemini's task types make. Anything implementing them plugs into every LangChain vector store.

```python
# claims_chain.py
class GeminiEmbeddings(Embeddings):
    """Chapter 4's `embed()` behind LangChain's `Embeddings` interface.

    Two methods are the whole contract, and the split between them is the same one chapter 4
    makes with Gemini's task types: a document going into an index and a query searching it are
    embedded differently. Anything implementing these two plugs into every LangChain vector store.
    """

    def embed_documents(self, texts):
        from stores import embed
        return embed(texts, task="RETRIEVAL_DOCUMENT")

    def embed_query(self, text):
        from stores import embed
        return embed([text], task="RETRIEVAL_QUERY")[0]

def clause_documents():
    """One Document per clause: the clause is the unit a reply cites, so it is the unit retrieved."""
    return [Document(page_content=f"{number} {section}: {text}", metadata={"clause": number, "section": section})
            for number, (section, text) in M.WORDING.items()]

def build_retriever(embeddings=None, k=4):
    store = InMemoryVectorStore(embeddings or GeminiEmbeddings())
    store.add_documents(clause_documents())
    return store.as_retriever(search_kwargs={"k": k}).with_config(run_name="retrieve")
