            if abs(rec["amount"] - allowed) > 0.01:
                update["trail"].append(f"investigator proposed {rec['amount']:,.2f}; policy allows {allowed:,.2f}")
            update |= {"amount": allowed, "qty": qty, "signers": P.approvers(invoice, allowed)}
        return update

    def query_vendor(state):
        invoice, rec = state["invoice"], state["recommendation"]
        body = draft(vendor=invoice["vendor_name"], invoice_number=invoice["invoice_number"],
                     po=invoice["po_number"], reason=rec["reason"])
        return {"outbox": [{"to": invoice["sender_email"], "body": body}],
                "vendor_rounds": state.get("vendor_rounds", 0) + 1,
                "trail": [f"wrote to {invoice['sender_email']}"]}

    def await_vendor(state):
        # Its own node, separate from the one that sends. A node that is resumed runs again from
        # its first line, so a send placed before this interrupt would go out twice.
        reply = interrupt({"ask": "vendor", "to": state["invoice"]["sender_email"],
                           "question": "Waiting for a corrected invoice."})
        return {"email": reply, "trail": ["vendor replied"]}

    def request_approval(state):
        signed = [a["by"] for a in state.get("approvals", [])]
        signer = next(s for s in state["signers"] if s not in signed)
        answer = interrupt({"ask": "approval", "approver": signer, "to": signer, "packet": _packet(state)})
        return {"approvals": [{"by": signer, "approved": bool(answer.get("approved")),
                               "note": answer.get("note", "")}],
                "trail": [f"{signer} {'approved' if answer.get('approved') else 'refused'}"]}

    def pay(state):
        row = P.schedule_payment(state["key"], state["invoice"], state["amount"], state.get("qty"))
        return {"status": "scheduled", "trail": [f"payment {row['ref']} scheduled: {row['amount']:,.2f}"]}

    def hold(state):
        return {"status": "held", "amount": 0.0, "trail": ["held for a person"]}

    def refused(state):
        return {"status": "refused", "amount": 0.0}

    # ------------------------------------------------------------ routing: code, never a model
    def after_check(state):
        kinds = {f["kind"] for f in state["findings"]}
        if not kinds:
            return "request_approval" if state["signers"] else "pay"
        for kind, node in [("duplicate", "answer_duplicate"), ("bank", "verify_bank"),
                           ("no_po", "ask_clerk"), ("unknown_vendor", "hold"), ("wrong_po", "hold")]:
            if kind in kinds:
                return node
        return "investigate"          # price or quantity

# --------------------------------------------------------------------------- driving it

def config(key, run=""):
    return {"configurable": {"thread_id": f"invoice-{key}{run}"}}


def waiting_on(graph, cfg):
    """The questions a paused thread is waiting on, or [] if it is not paused."""
    return [i.value for i in graph.get_state(cfg).interrupts]


def start(graph, key, run=""):
    """Begin one invoice. Returns what it is now waiting for, or [] if it finished."""
    graph.invoke({"key": key, "email": P.INBOX[key], "vendor_rounds": 0}, config(key, run))
    return waiting_on(graph, config(key, run))


def answer(graph, key, reply, run=""):
    """Resume a paused invoice with a person's (or a vendor's) reply."""
    graph.invoke(Command(resume=reply), config(key, run))
    return waiting_on(graph, config(key, run))


def settle(graph, key, run="", respond=P.human, max_answers=6):
    """Run one invoice to the end, answering every question from `payables.HUMANS`."""
    asks = start(graph, key, run)
    answered = 0
    while asks and answered < max_answers:
        ask = asks[0]
        asks = answer(graph, key, respond(key, ask["ask"], ask.get("approver")), run)
        answered += 1
    return graph.get_state(config(key, run)).values

def query_vendor(case):
        invoice, rec = case.values["invoice"], case.values["recommendation"]
        send(case, invoice["sender_email"], draft(vendor=invoice["vendor_name"], invoice_number=invoice["invoice_number"],
                                                  po=invoice["po_number"], reason=rec["reason"]))
        case.set("desk", "vendor_rounds", case.values.get("vendor_rounds", 0) + 1)
        # the email is sent and this step is over; the reply starts `read_reply`, so nothing is sent twice
        return Wait("vendor_reply", "vendor", then="read_reply", shown={
            "ask": "vendor", "to": invoice["sender_email"], "question": "Waiting for a corrected invoice."})

    def read_reply(case):
        case.set("desk", "email", case.values["vendor_reply"])
        return "read_invoice"

    def request_approval(case):
        signer = _next_signer(case)
        return Wait(f"approval:{signer}", signer, then="record_approval",
                    shown={"ask": "approval", "approver": signer, "to": signer, "packet": _packet(case.values)})

    def record_approval(case):
        signer = _next_signer(case)
        reply = case.values[f"approval:{signer}"]
        signed = case.values.get("approvals", []) + [{"by": signer, "approved": bool(reply.get("approved")),
                                                      "note": reply.get("note", "")}]
        case.set("desk", "approvals", signed)
        if not signed[-1]["approved"]:
            return close(case, "refused")
        return "pay" if {a["by"] for a in signed} >= set(case.values["signers"]) else "request_approval"

    def pay(case):
        row = P.schedule_payment(case.values["key"], case.values["invoice"], case.values["amount"],
                                 case.values.get("qty"))
        case.set("desk", "payment", row["ref"])
        case.set("desk", "status", "scheduled")
        return END

    def hold(case):
        return close(case, "held")

    steps = {"read_invoice": read_invoice, "check_policy": check_policy, "answer_duplicate": answer_duplicate,
             "verify_bank": verify_bank, "after_callback": after_callback, "ask_clerk": ask_clerk,
             "after_clerk": after_clerk, "investigate": investigate_step, "query_vendor": query_vendor,
             "read_reply": read_reply, "request_approval": request_approval, "record_approval": record_approval,
             "pay": pay, "hold": hold}
    return Desk(steps, start="read_invoice", fields=FIELDS, owner=OWNER, path=path)

def send(case, to, body):
    case.set("desk", "outbox", case.values.get("outbox", []) + [{"to": to, "body": body}])


def close(case, status):
    """Every ending but a payment: nothing is paid."""
    case.set("desk", "amount", 0.0)
    case.set("desk", "status", status)
    return END


def _next_signer(case):
    signed = [a["by"] for a in case.values.get("approvals", [])]
    return next(s for s in case.values["signers"] if s not in signed)


def _packet(values):
    inv = values["invoice"]
    lines = [f"{P.VENDORS[P.find_vendor(inv)]['name']} {inv['invoice_number']} against "
             f"{inv.get('po_number') or 'no PO'}: billed {inv['total']:,.2f}, to pay {values['amount']:,.2f}."]
    rec = values.get("recommendation")
    if rec and rec["invoice_number"] == inv["invoice_number"]:
        lines.append(f"Investigation: {rec['reason']}")
    if values.get("owner"):
        lines.append(f"Non-PO spend; the AP clerk found the requester: {P.PEOPLE[values['owner']]}.")
    return " ".join(lines)


def settle(desk, key, run="", respond=P.human, max_answers=6):
    """Run one invoice to the end, answering every question from `payables.HUMANS`."""
    thread = f"invoice-{key}{run}"
    waiting = desk.open(thread, {"key": key, "email": P.INBOX[key], "vendor_rounds": 0})
    answered = 0
    while waiting and answered < max_answers:
        reply = respond(key, waiting["ask"], waiting.get("approver"))
        waiting = desk.answer(thread, waiting["party"], waiting["field"], reply)
        answered += 1
    return desk.state(thread)

class CaseFile(Shared):
    """A chapter 6 board whose every write is also a row in a chapter 4 `Records` table.

    `Records` has columns for a feed of events, and a write to a board is one: `kind` holds the
    field, `status` who wrote it, `service` which case, `text` the value as JSON.
    """

    def __init__(self, log, thread, **board):
        super().__init__(**board)
        self.log, self.thread = log, thread
        # Rebuilt from the rows, in the order they were written. The owner check is not run again:
        # it ran when each row was written, which is the only time it means anything.
        for row in log.db.execute("SELECT kind, status, text FROM records WHERE service = ? ORDER BY id",
                                  (thread,)):
            before = self.values.get(row["kind"])
            self.values[row["kind"]] = json.loads(row["text"])
            self.history.append({"author": row["status"], "field": row["kind"], "from": before,
                                 "to": self.values[row["kind"]]})

    def set(self, author, field, value):
        if field not in self.owner:
            # chapter 6's board lets anyone write a field nobody owns. A case file holding money does not.
            raise Denied(f"{field} has no owner, so nobody may write it")
        before = super().set(author, field, value)          # raises Denied for anyone but the owner
        self.log.write(datetime.now().isoformat(), field, author, self.thread, json.dumps(value))
        return before


class Desk:
    """Steps over case files. Every case lives in one SQLite file, so any process can carry one on."""

    def __init__(self, steps, start, fields, owner, path=":memory:"):
        self.steps, self.start = dict(steps), start
        self.fields, self.owner = fields, owner
        self.log = Records(path)

    def case(self, thread):
        return CaseFile(self.log, thread, fields=self.fields, owner=self.owner)

    def open(self, thread, opening):
        """Start a case with the desk's opening facts. Returns what it waits on, or None if it finished."""
        case = self.case(thread)
        for name, value in opening.items():
            case.set("desk", name, value)
        case.set("desk", "next", self.start)
        return self._go(case)

    def answer(self, thread, party, field, value):
        """`party` answers the case's question by writing `field`. Then the step the question named runs."""
        case = self.case(thread)
        waiting = case.values.get("waiting")
        if not waiting or waiting["field"] != field:
            raise ValueError(f"{thread} is not waiting on {field!r} (waiting on: {waiting})")
        case.set(party, field, value)                       # only the field's owner gets past this
        case.set("desk", "waiting", None)
        case.set("desk", "next", waiting["then"])
        return self._go(case)

    def resume(self, thread):
        """Carry on a case whose step failed part-way: that step runs again."""
        return self._go(self.case(thread))

    def _go(self, case):
        while case.values.get("next") not in (None, END):
            after = self.steps[case.values["next"]](case)
            if isinstance(after, Wait):
                case.set("desk", "waiting", after.ask())
                case.set("desk", "next", None)
                return case.values["waiting"]
            case.set("desk", "next", after or END)
        return None

    def state(self, thread):
        case = self.case(thread)
        return {**case.values, "trail": [f"{w['author']}: {w['field']} = {_short(w['field'], w['to'])}"
                                         for w in case.history if w["field"] not in BOOKKEEPING]}

    def waiting(self, thread):
        return self.case(thread).values.get("waiting")

    def history(self, thread):
        return self.case(thread).history

def _short(field, value):
    """One readable line for a write, for the trail."""
    if isinstance(value, dict) and "action" in value:
        return f"{value['action']} -- {value['reason']}"
    if isinstance(value, dict) and "vendor_name" in value:
        return f"{value['invoice_number']} from {value['vendor_name']}"
    if field == "findings":
        return ", ".join(f["kind"] for f in value) or "matched"
    if field == "outbox":
        return f"wrote to {value[-1]['to']}"
    if isinstance(value, float):
        return f"{value:,.2f}"
    text = " ".join(str(value).split())
    return text if len(text) <= 120 else text[:117] + "..."

def _po_line(po, line):
    """The PO line an invoice line is billing for: by item code, or by the code inside its text.

    The fallback is there because a model reading "CB-7 controller board rev 7" may put CB-7 in
    `sku` or leave `sku` empty and keep it in the description -- both are fair readings of the
    email, measured in notebook 1, and only one of them would match on code alone. An invoice
    should not be held because of which of two correct readings the model chose.
    """
    for po_line in po["lines"]:
        if line["sku"] == po_line["sku"] or (not line["sku"] and po_line["sku"] in line["description"]):
            return po_line
    return None


def billed_qty(po, sku, exclude=None):
    return sum(p["qty"] for p in PAID + PAYMENTS
               if p["po"] == po and p["sku"] == sku and p["invoice"] != exclude)


def received_qty(po, sku):
    return sum(r["qty"] for r in RECEIPTS if r["po"] == po and r["sku"] == sku)

def billed_against(po_number: Annotated[str, "A purchase order number"]) -> str:
    """Invoices already paid against a PO."""
    rows = [p for p in PAID + PAYMENTS if p["po"] == po_number.strip().upper()]
    if not rows:
        return f"Nothing has been paid against {po_number} yet."
    return "\n".join(f"{p['invoice']}: {p['qty']} x {p['sku']}, {p['amount']:.2f}, paid {p['paid']} "
                     f"({p['ref']})" for p in rows)


def vendor_record(vendor_name: Annotated[str, "The vendor's name, e.g. Halvorsen Metals"]) -> str:
    """The vendor master record: payment terms and the contact details on file."""
    for vendor in VENDORS.values():
        if vendor["name"].split()[0].lower() in vendor_name.lower():
            return (f"{vendor['name']}: terms {vendor['terms']}, writes from @{vendor['domain']}, "
                    f"phone on file {vendor['phone']}.")
    return f"No vendor on file matches {vendor_name}."


