def overlap(tasks):
    """Each task's start and end, relative to the first start, and which specialist tasks overlapped."""
    timed = [t for t in tasks if t.get("start") and t.get("end")]
    if not timed:
        return {}
    zero = min(t["start"] for t in timed)
    spans = {t["task"]: (round((t["start"] - zero).total_seconds(), 1), round((t["end"] - zero).total_seconds(), 1))
             for t in timed}
    specialists = [spans[r] for r in T.ROLES if r in spans]
    together = all(a[0] < b[1] and b[0] < a[1] for i, a in enumerate(specialists) for b in specialists[i + 1:])
    return {"seconds from start": spans, "the three specialist tasks overlapped": together}


def report(questionnaire, width=150):
    """A questionnaire read against the key: each answer, what the pack supports, and the trap."""
    if questionnaire is None:
        print("no questionnaire")
        return 0
    rows = {row["id"]: row for row in T.grade(questionnaire)}
    by_id = {a.id: a for a in questionnaire.answers}
    for qid, (_, question) in T.QUESTIONS.items():
        row, answer = rows[qid], by_id.get(qid)
        mark = "ok " if row["right"] else "BAD"
        print(f"{qid} {mark} {row['status'] or '-':8} (key: {row['want']:8}) evidence {answer.evidence if answer else '-'}"
              + (f"  missing {row['missing evidence']}" if row["missing evidence"] else "")
              + ("  [needs review]" if answer and answer.needs_review else ""))
        if answer:
            print(f"     {answer.answer[:width]}")
    right = sum(row["right"] for row in rows.values())
    print(f"\n{right} of {len(rows)} with the status the policy pack supports")
    return right

class Desk:
    """The specialists and the lead. `answer` is chapter 6's `attempt`, injectable so it can be stubbed."""

    def __init__(self, answer=None, agents=None, retries=2):
        self.answer = answer or live_answer
        self.agents = agents or (make_agents() if answer is None else {r: r for r in (*T.ROLES, "lead")})
        self.retries = retries
        self.log = []

    def section(self, role):
        """One specialist's answers, checked by `tallyfold.check_section` and sent back if they fail."""
        request = f"{T.INSTRUCTIONS}\n\nYour questions:\n{T.questions_for(role)}"
        feedback = ""
        for attempt in range(self.retries + 1):
            form = self.answer(self.agents[role], request + (f"\n\n{feedback}" if feedback else ""), T.Section)
            if failed(form):
                # it raised, was stopped, or would not use the form: another whole run is unlikely to
                # go differently, so it is reported, not retried (chapter 6's `attempt`, retries=0)
                self.log.append({"step": f"{role}, attempt {attempt + 1}", "failed": failed(form)})
                return form
            problems = (T.check_section(form, role) if isinstance(form, T.Section)
                        else ["the specialist did not return its answers as the form"])
            self.log.append({"step": f"{role}, attempt {attempt + 1}", "problems": problems})
            if not problems:
                return form
            feedback = "Fix these and return all your answers again:\n- " + "\n- ".join(problems)
        return form

    def assemble(self, sections, feedback=""):
        answers = json.dumps({role: s.model_dump() if isinstance(s, T.Section) else str(s)
                              for role, s in sections.items()}, indent=1)
        request = ("Assemble Harrow & Pike's security questionnaire from the specialists' answers below. Keep every "
                   "fact, status and statement id exactly as the specialist gave it; make the wording consistent; "
                   "answer every question exactly once; and write notes for sales on what will disappoint the "
                   f"customer.\n\nThe questionnaire:\n" + "\n".join(f"{q}: {t}" for q, (_, t) in T.QUESTIONS.items())
                   + f"\n\nThe specialists' answers:\n{answers}" + (f"\n\n{feedback}" if feedback else ""))
        return self.answer(self.agents["lead"], request, T.Questionnaire)

    def run(self):
        with concurrent.futures.ThreadPoolExecutor(max_workers=3) as pool:
            sections = dict(zip(T.ROLES, pool.map(self.section, T.ROLES)))
        holes = {role: failed(form) for role, form in sections.items() if failed(form)}
        if holes:
            # a lead handed a missing section would answer those questions itself, from nothing
            return {"questionnaire": None, "sections": sections, "failed": holes}
        feedback = ""
        for attempt in range(self.retries + 1):
            questionnaire = self.assemble(sections, feedback)
            if failed(questionnaire):
                self.log.append({"step": f"assemble, attempt {attempt + 1}", "failed": failed(questionnaire)})
                return {"questionnaire": None, "sections": sections, "failed": {"lead": failed(questionnaire)}}
            problems = (T.check(questionnaire) if isinstance(questionnaire, T.Questionnaire)
                        else ["the lead did not return a questionnaire"])
            self.log.append({"step": f"assemble, attempt {attempt + 1}", "problems": problems})
            if not problems:
                return {"questionnaire": questionnaire, "sections": sections}
            feedback = "Fix these and return the whole questionnaire again:\n- " + "\n- ".join(problems)
        return {"questionnaire": None, "sections": sections}

"""What building the analysis team found out about AutoGen, each one reproducible offline.

    event_loops        AutoGen's code executor under the event loop a script runs and the one Jupyter runs
    secrets            what model-written code can read: AutoGen's executor against this project's
    gate_examples      what `brightwater.gate` stops -- and one way straight past it
    termination        a reviewer that never approves: which of the four conditions ends the chat
    traps              what the three questions give on the export as it stands, and once cleaned
"""

import asyncio
import json
import tempfile
from pathlib import Path

import a_stubs as S
import analysis_team as AT
import brightwater as B

_PEEK = "import os\nprint(sorted(k for k in os.environ if k.endswith('API_KEY')))"


async def _run(executor_class, code):
    from autogen_core import CancellationToken
    from autogen_core.code_executor import CodeBlock
    result = await executor_class(work_dir=tempfile.mkdtemp(), timeout=30).execute_code_blocks(
        [CodeBlock(code=code, language="python")], CancellationToken())
    return result.output.strip()


def _on_thread(fn, timeout=120):
    """`fn()` on a thread of its own. A Jupyter kernel's thread already runs an event loop, and one loop
    cannot be run inside another -- the same reason `run_team` gives each team a thread."""
    import threading
    box = {}

    def worker():
        try:
            box["value"] = fn()
        except Exception as failed:     # noqa: BLE001 -- what it raises is the finding
            box["value"] = f"{type(failed).__name__}: {failed}"

    thread = threading.Thread(target=worker, daemon=True)
    thread.start()
    thread.join(timeout)
    return box.get("value", f"did not finish within {timeout}s")


def event_loops():
    return _on_thread(_event_loops)


def _event_loops():
    from autogen_ext.code_executors.local import LocalCommandLineCodeExecutor
    found = {}
    for name, make in [("ProactorEventLoop (a script's default)", asyncio.ProactorEventLoop),
                       ("SelectorEventLoop (what a Jupyter kernel runs on Windows)", asyncio.SelectorEventLoop)]:
        loop = make()
        try:
            found[name] = "ran: " + loop.run_until_complete(_run(LocalCommandLineCodeExecutor, "print('hello')"))
        except Exception as failed:     # noqa: BLE001 -- what it raises is the finding
            found[name] = f"{type(failed).__name__}: {failed}"
        finally:
            loop.close()
    return found


def secrets():
    return _on_thread(_secrets)


def _secrets():
    from autogen_ext.code_executors.local import LocalCommandLineCodeExecutor
    loop = asyncio.ProactorEventLoop()
    try:
        return {"AutoGen's executor -- the code can see": loop.run_until_complete(_run(LocalCommandLineCodeExecutor, _PEEK)),
                "this project's executor -- the code can see": loop.run_until_complete(_run(AT._executor_class(), _PEEK))}
    finally:
        loop.close()


def gate_examples():
