def termination():
    """A reviewer that never approves, against a replayed model: which condition stops it, and when."""
    import threading
    box = {}

    async def go():
        work_dir = tempfile.mkdtemp()
        B.write_orders(work_dir)
        team = AT.build_team(S.replay("Q1", approve=False), work_dir, max_messages=12)
        return await team.run(task=B.QUESTIONS["Q1"])

    def worker():
        loop = asyncio.ProactorEventLoop()
        try:
            box["result"] = loop.run_until_complete(go())
        except Exception as failed:     # noqa: BLE001
            box["error"] = f"{type(failed).__name__}: {failed}"
        finally:
            loop.close()

    thread = threading.Thread(target=worker, daemon=True)
    thread.start()
    thread.join(120)
    if "error" in box:
        return {"error": box["error"]}
    result = box["result"]
    return {"messages": len(result.messages), "stop_reason": result.stop_reason,
            "speakers": [m.source for m in result.messages if type(m).__name__ in ("TextMessage",)]}


def traps():
    clean, naive = B.truth(), B.naive()
    return {qid: {"the export as it stands": (naive["duplicates kept"][qid]["entity"], naive["duplicates kept"][qid]["value"]),
                  "duplicates kept AND returns counted": (naive["duplicates kept, returns counted"][qid]["entity"],
                                                          naive["duplicates kept, returns counted"][qid]["value"]),
                  "cleaned (the truth)": (clean[qid]["entity"], clean[qid]["value"])}
            for qid in B.QUESTIONS}


def show_run(qid, out, width=320):
    """One run, read the way a reviewer would: who said what, what the code printed, the finding, the grade."""
    if out.get("error"):
        print("error:", out["error"])
    for turn in out["turns"][1:]:
        if turn.get("kind") == "CodeGenerationEvent":
            continue                                    # the code is long; what it printed is below
        text = " ".join(turn["text"].split())
        print(f"--- {turn['source']}{' (code ran)' if turn.get('kind') == 'CodeExecutionEvent' else ''}: "
              f"{text[:width]}{'...' if len(text) > width else ''}")
    graded = B.grade(qid, out["finding"])
    print(f"\n{'RIGHT' if graded['right'] else 'WRONG'}: answered {graded['entity']} {graded['value']}, "
          f"the truth is {graded['want'][0]} {graded['want'][1]}")
    return graded["right"]


def checked_duplicates(out):
    """Whether any program the analyst ran looked for repeated rows -- the step Q1 needs."""
    return any(".duplicated(" in t["text"] or "drop_duplicates(" in t["text"] for t in out.get("turns", []))


def skills_report(qid, out):
    """What the planner read, against what the question needed, and whether the analysis then did it."""
    read, needed = out.get("skills read", []), B.RELEVANT.get(qid, set())
    return {"read": read, "needed and read": sorted(needed & set(read)), "needed, not read": sorted(needed - set(read)),
            "read, not needed": sorted(set(read) - needed), "the analysis checked for duplicates": checked_duplicates(out)}


STORE = Path(__file__).resolve().parent / "store"

def route(source, content):
    """Who speaks after `source`. Shared with the scratch build, so both teams are routed by the same rules.

    A review is a `Review` form, so who fixes what is a field the reviewer filled in, not a word to look
    for in its prose. None only if the reviewer answered in prose, when the selector model reads it.
    """
    if source == "user":
        return "planner"
    if source == "planner":
        return "analyst"
    if source == "analyst":
        return "reviewer"
    if source == "reviewer":
        if isinstance(content, B.Review):
            return "reporter" if content.approved else ("planner" if content.fix_by == "planner" else "analyst")
        return None
    return None


def next_speaker(messages):
    """AutoGen's `selector_func`: the routing rules, applied to the last message in the chat."""
    last = messages[-1]
    return route(last.source, getattr(last, "content", ""))


def rejections(messages):
    """How many reviews in a chat did not approve."""
    return sum(1 for m in messages if isinstance(getattr(m, "content", None), B.Review) and not m.content.approved)


MAX_REJECTIONS = 2       # the first sends the work back once; the second hands it to a person

def naive():
    """What the same questions give on the export as it stands: duplicates kept; and returns counted too."""
    return {"duplicates kept": _answers(_frame(clean=False)),
            "duplicates kept, returns counted": _answers(_frame(clean=False), exclude_returns=False)}


# --------------------------------------------------------------------------- the form, and grading

class Finding(BaseModel):
    """One answer, as the commercial team will read it."""

    entity: str = Field(description="The one-word answer: a region, a category, or yes / no.")
    value: float = Field(description="The key figure, as a percentage, rounded to one decimal place.")
    answer: str = Field(description="Two or three sentences for the commercial team.")
    data_issues: list[str] = Field(description="Every problem found in the data and what was done about it. "
                                               "Empty if none was found.")


class Review(BaseModel):
    """The reviewer's verdict, as fields the routing can act on rather than a word to search for."""

    approved: bool = Field(description="True only if the code and its output, shown in the analyst's report, "
                                       "answer the question as it is defined.")
    problems: list[str] = Field(default_factory=list,
                                description="Each problem, specific enough to act on: what is wrong in the code or "
                                            "output, and what must be done about it. Empty if approved.")
    fix_by: Literal["analyst", "planner", "nobody"] = Field(
        description="analyst for a calculation or a data problem, planner for a wrong method, nobody if approved.")

    def render(self):
        if self.approved:
            return "APPROVED"
        return f"NOT APPROVED -- for the {self.fix_by}:\n" + "\n".join(f"- {p}" for p in self.problems)


def grade(qid, finding, tolerance=0.5):
    """Right entity, and a figure within `tolerance` percentage points of the truth."""
    want = truth()[qid]
    if finding is None:
        return {"right": False, "entity": None, "value": None, "want": (want["entity"], want["value"])}
    right = (finding.entity.strip().lower() == str(want["entity"]).lower()
             and abs(finding.value - want["value"]) <= tolerance)
    return {"right": right, "entity": finding.entity, "value": finding.value, "want": (want["entity"], want["value"])}


# --------------------------------------------------------------------------- what code may not do

_FORBIDDEN = {
    r"\bos\.environ\b|\bgetenv\b|\bdotenv\b": "reads environment variables",
    r"\bsubprocess\b|\bos\.system\b|\bos\.popen\b|\bpty\b": "starts other programs",
    r"\bsocket\b|\brequests\b|\burllib\b|\bhttpx\b|\baiohttp\b": "uses the network",
    r"\bshutil\.rmtree\b|\bos\.remove\b|\bos\.unlink\b|\brmdir\b": "deletes files",
    r"\.\./|\.\.\\\\|\b[A-Za-z]:\\\\": "reaches outside its working folder",
    r"\b__import__\b|\bexec\(|\beval\(|\bimportlib\b": "builds code at run time",
}


def gate(code):
    """(True, "") if the code may run; otherwise (False, why). Checked before every execution.

    A list of patterns, which a determined author gets past ("o" + "s"). It stops the accidents --
    a model reaching for an API key to "check the configuration", or deleting a file it made -- and
    says no out loud. It is not a sandbox; without Docker there is none here, which is why the
    executor is also given an environment with the secrets taken out.
    """
    for pattern, why in _FORBIDDEN.items():
        if re.search(pattern, code):
            return False, f"refused: the code {why}"
    return True, ""


# --------------------------------------------------------------------------- the team's procedures

# Procedural memory, in chapter 4's terms: how-to the team has learned, kept for the next job. Nine
# procedures, written generically -- none names this export or its problems -- and only three bear on

class Team:
"""The four people and the case file. `answer(name, request, form)` replaces every model call offline."""

    def __init__(self, work_dir=None, answer=None, max_turns=AT.MAX_MESSAGES, qid="?", skills=False):
        from state import Shared
        self.label = f"scratch {qid}"
        self.work_dir = work_dir or tempfile.mkdtemp(prefix="brightwater-")
        B.write_orders(self.work_dir)
        self.board = Shared(fields=FIELDS, owner=OWNER, readers=READERS)
        self.refused = []
        self.reviews = []
        self.max_turns = max_turns
        self.answer = answer
        self.run_python = python_runner(self.work_dir, self.board, label=self.label, refused=self.refused)
        self.skills, self.skills_read = skills, []
        self.agents = self._agents()

    def read_skill(self, name: Annotated[str, "The procedure's name, exactly as listed"]) -> str:
        """The full text of one of the team's procedures."""
        self.skills_read.append(name)
        return B.read_skill(name)

    def _agents(self):
        from registry import Registry
        from supervisor import Agent
        from tools import Tool
        # with `skills`, the planner may read the team's procedures through a chapter 3 tool -- the same
        # text and the same catalogue the AutoGen planner gets
        planner = (Agent("planner", AT.PLANNER_WITH_SKILLS, model=MODEL,
                         tools=Registry([Tool(self.read_skill, name="read_skill",
                                              description=B.READ_SKILL_DESCRIPTION)]))
                   if self.skills else Agent("planner", AT.PLANNER, model=MODEL))
        return {"planner": planner,
                "analyst": Agent("analyst", ANALYST, tools=Registry([Tool(self.run_python)]), model=MODEL),
                "reviewer": Agent("reviewer", REVIEWER, model=MODEL),
                "reporter": Agent("reporter", AT.REPORTER, model=MODEL)}

    def _ask(self, name, request, form=None):
        if self.answer is not None:
            return self.answer(name, request, form)
        if form is None:
            return self.agents[name].run(request)
        # The reviewer and the reporter have no tools: they read and fill in a form. An agent loop that
        # finishes by calling a `submit` tool would let the model answer in prose instead. Chapter 1's
        # `extract()` asks the provider to enforce the form's schema, so the reply IS the form, and validates
        # and retries behind that -- what AutoGen's `output_content_type` does.
        from failures import failure
        from llm import extract
        agent = self.agents[name]
        try:
            return extract(f"{agent.persona}\n\n{request}", form, model=agent.model)
        except ValueError as unusable:          # still not the form after extract's retries
            return failure(f"{name} did not fill in its form", str(unusable)[:200])

    def _turn(self, name, question):
        """One person's turn: they read their view of the case, and what they produce goes in their field."""
        request = f"The question: {question}\n\n{self.board.view(name)}\n\nYour turn."
        form = FORMS.get(name)
        said = self._ask(name, request, form)
        if form is not None and not isinstance(said, form):
            # a failure form from `attempt`: it raised, was stopped, or answered in prose
            return None, f"needs a person: {said.answer} -- {said.unknowns}"[:300]
        text = said.render() if name == "reviewer" else said.model_dump_json() if name == "reporter" else said
        self.board.set(name, WRITES[name], text)
        return said, None

def run(self, question, budget=AT.SCRATCH_BUDGET, qid="?"):
        """Answer one question, inside a `Budget`: every model call is counted, none made past `budget`."""
        finding, stop = None, None
        with Budget(budget, self.label) as spent:
            try:
                finding, stop = self._work(question)
            except AT.BudgetExceeded:
                pass
        stop = spent.over or stop          # a form turn reports the budget as its own failure
        turns = [{"source": "user", "text": question}] + [
            {"source": w["author"], "text": w["to"], "field": w["field"],
             **({"kind": "CodeExecutionEvent"} if w["author"] == "runner" else {})} for w in self.board.history]
        return {"finding": finding, "stop_reason": stop, "turns": turns,
                "speakers": [t["source"] for t in turns[1:] if t["source"] != "runner"],
                "refused": list(self.refused), "rejections": sum(not r.approved for r in self.reviews),
                "skills read": list(self.skills_read),
                "usage": spent.summary()}

    def _work(self, question):
        last, said = "user", question
        for _ in range(self.max_turns - 1):
            name = AT.route(last, said)
            said, failed = self._turn(name, question)
            if failed:
                return None, failed
            if name == "reporter":
                return said, grounded(said, self.board.values.get("evidence")) or "reporter answered"
            if name == "reviewer":
                self.reviews.append(said)
                if sum(not r.approved for r in self.reviews) >= AT.MAX_REJECTIONS:
                    return None, "needs a person: the second review did not approve"
            last = name
        return None, "too many turns"
